using System.Collections.Generic;
using Verse;

namespace RimMandrake.Minerals
{
    /// <summary>One biome cell of a registry row: a number in the row's unit, or a token (deep-only, herd, unbounded).
    /// The biome is a defName string so a column naming a biome of an absent mod is harmless.</summary>
    public class RM_MineralBiomeCell
    {
        public string biome;
        public float value;
        public string token;
    }

    /// <summary>One material of the mineral abundance registry (design/RimMandrake/mineral_abundance_registry_design_2026-10-03.md §5).
    /// GENERATED by src/RimMandrake/Utils/gen_mineral_registry.py (--registry-out) from the registry CSV; never hand-edited.
    /// Field names are exactly the generator's emitted tags.</summary>
    public class RM_MineralRegistryDef : Def
    {
        public static readonly string[] KnownUnits = { "EPM", "EPM/yr", "UPY", "deep share", "—" };   // = mineral_registry_check.UNITS

        public string materialId;
        public string status;
        public string form;
        public string unit;
        public float unitsPerCellOrFind;
        public float deepWeight;
        public float otherBiomes;
        public float salvagePerYear;
        public float tradePerYear;
        public bool quarryLocal;
        public float quarryPer100Jobs = -1f;          // -1 = "derive" (proportional to the biome's EPM)
        public List<ThingDef> items = new List<ThingDef>();
        public List<ThingDef> mineables = new List<ThingDef>();
        public List<ThingDef> producers = new List<ThingDef>();
        public List<string> zeroProducers = new List<string>();   // strings: a missing donor mod is harmless
        public List<string> retiredItems = new List<string>();
        public List<RM_MineralBiomeCell> biomes = new List<RM_MineralBiomeCell>();

        public override IEnumerable<string> ConfigErrors()
        {
            foreach (string e in base.ConfigErrors()) yield return e;
            if (materialId.NullOrEmpty()) yield return "RM_MineralRegistryDef " + defName + " has no materialId";
            if (unit.NullOrEmpty() || System.Array.IndexOf(KnownUnits, unit) < 0)
                yield return "RM_MineralRegistryDef " + defName + " has unknown unit '" + unit + "'";
            if (biomes != null)
                foreach (RM_MineralBiomeCell c in biomes)
                {
                    if (c == null || c.biome.NullOrEmpty()) yield return "RM_MineralRegistryDef " + defName + " has a biome cell with no biome";
                    else if (c.token != null && c.token != "deep-only" && c.token != "herd" && c.token != "unbounded")
                        yield return "RM_MineralRegistryDef " + defName + " biome " + c.biome + " has unknown token '" + c.token + "'";
                }
        }

        public MineralRow ToRow()
        {
            var r = new MineralRow
            {
                MaterialId = materialId,
                Unit = unit,
                UnitsPerCellOrFind = unitsPerCellOrFind,
                DeepWeight = deepWeight,
                OtherBiomes = otherBiomes,
                QuarryLocal = quarryLocal,
                QuarryPer100Jobs = quarryPer100Jobs,
            };
            if (items != null) foreach (ThingDef t in items) if (t != null) r.Items.Add(t.defName);
            if (mineables != null) foreach (ThingDef t in mineables) if (t != null) r.Mineables.Add(t.defName);
            if (producers != null) foreach (ThingDef t in producers) if (t != null) r.Producers.Add(t.defName);
            if (zeroProducers != null) foreach (string s in zeroProducers) if (!s.NullOrEmpty()) r.ZeroProducers.Add(s);
            if (retiredItems != null) foreach (string s in retiredItems) if (!s.NullOrEmpty()) r.RetiredItems.Add(s);
            if (biomes != null)
                foreach (RM_MineralBiomeCell c in biomes)
                {
                    if (c == null || c.biome.NullOrEmpty()) continue;
                    if (!c.token.NullOrEmpty()) r.Tokens[c.biome] = c.token;
                    else r.Cells[c.biome] = c.value;
                }
            return r;
        }
    }
}
